DROP TABLE IF EXISTS public."RULE";

CREATE TABLE public."RULE" (
    "RULE_ID"                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "RULE_CATALOG_ID"         integer,
    "RULE_NAME"               varchar(100),
    "RULE_DESCRIPTION"        varchar(512),
    "IS_ACTIVE"               numeric(38,0),
    "EXCEPTION_TYPE_ID"       numeric(38,0),
    "EXCEPTION_PROCESS_TYPE_ID"  numeric,
    "EXCEPTION_SEVERITY_TYPE_ID" numeric,
    "EXCEPTION_PRIORITY_TYPE_ID" numeric,
    "EXCEPTION_SOURCE"        numeric,
    "CREATED_BY"              varchar(100),
    "CREATED_DATE"            timestamp
);

INSERT INTO public."RULE" (
