    "EXCEPTION_TYPE_ID", "EXCEPTION_PROCESS_TYPE_ID", "EXCEPTION_SEVERITY_TYPE_ID",
    "EXCEPTION_PRIORITY_TYPE_ID", "EXCEPTION_SOURCE", "CREATED_BY", "CREATED_DATE"
) VALUES
